// keyjack half-fixed client (minified; key removed from source, fetched at runtime). The key still reaches the browser over /api/client-config, so minifying and runtime-delivery change nothing.
const $=i=>document.getElementById(i);let M=null,C=[],K=null;
const A=(p,o={})=>fetch(p,{credentials:"same-origin",headers:{"Content-Type":"application/json",...(o.headers||{})},...o}).then(async r=>({ok:r.ok,status:r.status,body:r.headers.get("content-type")?.includes("application/json")?await r.json():null}));
const $m=c=>"$"+(c/100).toFixed(2);
async function key(){if(K===null){K=(await A("/api/client-config")).body.signing_key}return K}
function canon(o){const L=[`part_number=${o.part_number}`,`quantity=${o.quantity}`,`work_order_id=${o.work_order_id}`,`unit_price_cents=${o.unit_price_cents}`,`restricted=${o.restricted?"true":"false"}`,`line_total_cents=${o.line_total_cents}`];if(o.within_limit!==undefined)L.push(`within_limit=${o.within_limit?"true":"false"}`);if(o.requires_supervisor!==undefined)L.push(`requires_supervisor=${o.requires_supervisor?"true":"false"}`);return L.join("\n")}
async function sign(m){const e=new TextEncoder(),k=await crypto.subtle.importKey("raw",e.encode(await key()),{name:"HMAC",hash:"SHA-256"},false,["sign"]),s=await crypto.subtle.sign("HMAC",k,e.encode(m));return[...new Uint8Array(s)].map(b=>b.toString(16).padStart(2,"0")).join("")}
async function refresh(){const m=await A("/api/me");if(!m.ok){M=null;$("login-view").hidden=false;$("app-view").hidden=true;return}M=m.body;$("login-view").hidden=true;$("app-view").hidden=false;$("whoami").textContent=`Signed in as ${M.display_name} (${M.id})`+(M.approval_limit_cents!=null?` · limit ${$m(M.approval_limit_cents)}`:"");C=(await A("/api/catalog")).body||[];$("part-select").innerHTML=C.map(p=>`<option value="${p.part_number}">${p.part_number} — ${p.name} · ${$m(p.unit_price_cents)}${p.restricted?" · restricted":""}</option>`).join("");$("work-order-select").innerHTML=((await A("/api/work-orders")).body||[]).map(w=>`<option value="${w.id}">${w.id} — ${w.description}</option>`).join("");await orders();const s=M.role==="supervisor";$("supervisor-console").hidden=!s;if(s)await sup()}
async function orders(){$("orders-table").querySelector("tbody").innerHTML=((await A("/api/orders")).body||[]).map(o=>`<tr><td>${o.id}</td><td>${o.account_id}</td><td>${o.part_number}</td><td>${o.quantity}</td><td>${$m(o.line_total_cents)}</td><td>${o.state}</td></tr>`).join("")}
async function sup(){const p=((await A("/api/orders")).body||[]).filter(o=>o.state==="pending_supervisor");$("pending-list").innerHTML=p.map(o=>`<div class="pending-row" data-order="${o.id}"><span>${o.id} · ${o.account_id} · ${o.part_number}</span><button class="approve" data-order="${o.id}">Approve</button><button class="reject" data-order="${o.id}">Reject</button></div>`).join("")||"<p>No pending orders.</p>"}
document.addEventListener("DOMContentLoaded",()=>{$("login-form").addEventListener("submit",async e=>{e.preventDefault();const r=await A("/api/login",{method:"POST",body:JSON.stringify({account_id:$("account-id").value,password:$("password").value})});$("message").textContent=r.ok?"":"Sign-in failed.";if(r.ok)await refresh()});$("logout-btn").addEventListener("click",async()=>{await A("/api/logout",{method:"POST"});await refresh()});$("order-form").addEventListener("submit",async e=>{e.preventDefault();const p=C.find(x=>x.part_number===$("part-select").value),q=Math.max(1,parseInt($("quantity").value||"1",10)),lt=p.unit_price_cents*q,wl=lt<=M.approval_limit_cents,o={part_number:p.part_number,quantity:q,work_order_id:$("work-order-select").value,unit_price_cents:p.unit_price_cents,restricted:p.restricted,line_total_cents:lt,within_limit:wl,requires_supervisor:p.restricted||!wl},sig=await sign(canon(o));const r=await A("/api/orders",{method:"POST",headers:{"X-Ninebark-Signature":sig},body:JSON.stringify(o)});$("message").textContent=r.ok?`Order ${r.body.id}: ${r.body.state}`:"Order refused.";await orders();if(M&&M.role==="supervisor")await sup()});$("pending-list").addEventListener("click",async e=>{const t=e.target;if(!(t instanceof HTMLElement))return;const id=t.getAttribute("data-order");if(!id)return;if(t.classList.contains("approve"))await A(`/api/orders/${id}/approve`,{method:"POST"});else if(t.classList.contains("reject"))await A(`/api/orders/${id}/reject`,{method:"POST"});await orders();await sup()});$("pickup-form").addEventListener("submit",async e=>{e.preventDefault();const r=await A("/api/pickup",{method:"POST",body:JSON.stringify({code:$("pickup-code").value})});$("message").textContent=r.ok?`Collected ${r.body.id}.`:"Pickup refused.";await orders()});refresh()});
